interface Prompt {
  readonly isInteractive: boolean;
  ask(question: string): Promise<string>;
}

declare function pushAdoptedBranch(prNumber: number): Promise<void>;

export async function adoptForkPullRequest(
  prNumber: number,
  authorHandle: string,
  prompt: Prompt,
): Promise<void> {
  if (!prompt.isInteractive) {
    throw new Error("interactive confirmation required");
  }

  const confirmation = await prompt.ask(`Type ${authorHandle} to confirm`);
  if (confirmation !== authorHandle) {
    throw new Error("confirmation mismatch");
  }

  await pushAdoptedBranch(prNumber);
}

